class Solution {
public:
    int projectionArea(vector<vector<int>>& grid) {
        int n = grid.size();
        int xy = 0, yz = 0, zx = 0;
        for (int r = 0; r < n; r++) {
            int row_max = 0;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] > 0) xy++;
                row_max = max(row_max, grid[r][c]);
            }
            zx += row_max;
        }
        for (int c = 0; c < n; c++) {
            int col_max = 0;
            for (int r = 0; r < n; r++) {
                col_max = max(col_max, grid[r][c]);
            }
            yz += col_max;
        }
        return xy + yz + zx;
    }
};

